WITH lowest AS (SELECT district_id FROM district ORDER BY A11 ASC LIMIT 1),
oldest AS (SELECT c.client_id FROM client c WHERE c.gender = 'F' AND c.district_id = (SELECT district_id FROM lowest) ORDER BY c.birth_date ASC LIMIT 1)
SELECT d.account_id, (SELECT MAX(A11) - MIN(A11) FROM district) AS salary_difference FROM disp d WHERE d.client_id = (SELECT client_id FROM oldest) ORDER BY d.account_id;

WITH abn_patients AS (
  SELECT DISTINCT l.ID FROM Laboratory l JOIN Patient p ON p.ID = l.ID
  WHERE p.Admission = '-' AND l.SSA IN ('1','4','16','64','256')
),
rnp AS (
  SELECT l.ID, CAST(l.RNP AS INTEGER) AS titer FROM Laboratory l
  WHERE l.ID IN (SELECT ID FROM abn_patients) AND l.RNP GLOB '[0-9]*'
)
SELECT ID, titer AS RNP_titer FROM rnp
WHERE titer = (SELECT MAX(titer) FROM rnp);

SELECT COUNT(*) AS patient_count
FROM Patient p
WHERE p.ID IN (
  SELECT l.ID FROM Laboratory l
  WHERE l.SSA IS NOT NULL AND l.SSA NOT IN ('negative', '0')
)
AND p.ID IN (
  SELECT l.ID FROM Laboratory l
  WHERE l.`U-PRO` IS NOT NULL AND l.`U-PRO` NOT IN ('-', 'negative')
);

SELECT ROUND(
  (SELECT COALESCE(SUM(spent), 0) FROM budget) * 1.0 / (SELECT COUNT(*) FROM event),
  2) AS average_spent_per_event;

WITH ad_events AS (
  SELECT DISTINCT link_to_event AS event_id FROM budget WHERE category = 'Advertisement'
),
per_event AS (
  SELECT e.event_id, (SELECT COUNT(*) FROM attendance a WHERE a.link_to_event = e.event_id) AS attendees
  FROM event e JOIN ad_events ad ON ad.event_id = e.event_id
)
SELECT ROUND(AVG(attendees), 2) AS avg_attendees_per_advertising_event FROM per_event;

WITH sle_visits AS (
  SELECT DISTINCT e.ID FROM Examination e
  WHERE EXISTS (
    SELECT 1 FROM json_each('["' || replace(replace(e.Diagnosis, '"', ''), ',', '","') || '"]') j
    WHERE trim(j.value) = 'SLE' OR trim(j.value) LIKE 'SLE+%'
  )
)
SELECT ROUND(AVG(l.TP - 8.5), 3) AS avg_deviation
FROM Laboratory l JOIN Patient p ON p.ID = l.ID
WHERE p.SEX = 'F' AND l.TP > 8.5 AND l.ID IN (SELECT ID FROM sle_visits);

WITH rc AS (
  SELECT c.id, c.name, c.artist, c.isPromo, COUNT(r.id) AS n
  FROM cards c LEFT JOIN rulings r ON r.uuid = c.uuid
  GROUP BY c.id
)
SELECT DISTINCT name, artist, isPromo FROM rc WHERE n = (SELECT MAX(n) FROM rc) ORDER BY name, artist, isPromo;

WITH fr AS (
  SELECT DISTINCT uuid FROM foreign_data WHERE language = 'French' AND uuid IS NOT NULL
),
target AS (
  SELECT uuid FROM cards WHERE power IS NULL OR power LIKE '%*%'
)
SELECT ROUND(100.0 * SUM(CASE WHEN uuid IN (SELECT uuid FROM fr) THEN 1 ELSE 0 END) / COUNT(*), 2) AS french_translation_percentage
FROM target;

WITH current_attr AS (
  SELECT * FROM (
    SELECT pa.*, ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) AS rn
    FROM Player_Attributes pa
  ) WHERE rn = 1
),
left_rated AS (
  SELECT attacking_work_rate FROM current_attr
  WHERE preferred_foot = 'left' AND attacking_work_rate IN ('high', 'medium', 'low')
)
SELECT ROUND(100.0 * SUM(attacking_work_rate = 'low') / COUNT(*), 1) AS low_attacking_work_rate_pct
FROM left_rated;

WITH abnormal_ssa AS (
  SELECT DISTINCT l.ID FROM Laboratory l JOIN Patient p ON p.ID = l.ID
  WHERE p.Admission = '-' AND l.SSA IS NOT NULL AND l.SSA NOT IN ('', 'negative', '0')
),
rnp AS (
  SELECT l.ID, CAST(l.RNP AS INTEGER) AS titer FROM Laboratory l
  WHERE l.ID IN (SELECT ID FROM abnormal_ssa) AND l.RNP GLOB '[0-9]*'
)
SELECT ID, titer FROM rnp WHERE titer = (SELECT MAX(titer) FROM rnp);

SELECT ROUND(
  (SELECT COUNT(*) FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE a.molecule_id = 'TR397') * 1.0
  / (SELECT COUNT(*) FROM atom WHERE molecule_id = 'TR397'), 2) AS avg_bonds_per_atom;

WITH cand AS (
  SELECT l.ID, l.Date, l.DNA, CAST(l.DNA AS REAL) AS lvl
  FROM Laboratory l JOIN Patient p ON p.ID = l.ID
  WHERE p.SEX = 'F' AND p.Admission = '+' AND l.DNA IS NOT NULL
)
SELECT ID, Date, DNA FROM cand WHERE lvl = (SELECT MAX(lvl) FROM cand) ORDER BY ID, Date;
